PRAGMA foreign_keys = ON;\n\nCREATE TABLE IF NOT EXISTS users (\n  id INTEGER PRIMARY KEY AUTOINCREMENT,\n  role TEXT CHECK(role IN ('customer','driver','admin')) NOT NULL,\n  name TEXT NOT NULL,\n  email TEXT UNIQUE NOT NULL,\n  phone TEXT,\n  status TEXT CHECK(status IN ('Active','Suspended','Blocked')) NOT NULL DEFAULT 'Active',\n  blocked_reason TEXT,\n  email_verified INTEGER NOT NULL DEFAULT 0,\n  phone_verified INTEGER NOT NULL DEFAULT 0,\n  created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,\n  last_active TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP\n);\n\nCREATE TABLE IF NOT EXISTS auth_passwords (\n  user_id INTEGER PRIMARY KEY,\n  password_hash TEXT NOT NULL,\n  FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE\n);\n\nCREATE TABLE IF NOT EXISTS driver_profiles (\n  user_id INTEGER PRIMARY KEY,\n  company_name TEXT,\n  vehicle_types TEXT,\n  trailer_types TEXT,\n  capacity TEXT,\n  regions TEXT,\n  availability TEXT,\n  insurance_doc_urls TEXT,\n  FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE\n);\n\nCREATE TABLE IF NOT EXISTS shipments (\n  id INTEGER PRIMARY KEY AUTOINCREMENT,\n  customer_id INTEGER NOT NULL,\n  pickup_city TEXT, pickup_address TEXT,\n  dropoff_city TEXT, dropoff_address TEXT,\n  pickup_window_start TEXT, pickup_window_end TEXT,\n  trailer_type TEXT, details TEXT,\n  weight REAL, volume REAL,\n  special_requirements TEXT,\n  budget REAL,\n  status TEXT NOT NULL,\n  created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,\n  FOREIGN KEY(customer_id) REFERENCES users(id) ON DELETE CASCADE\n);\n\nCREATE TABLE IF NOT EXISTS quotes (\n  id INTEGER PRIMARY KEY AUTOINCREMENT,\n  shipment_id INTEGER NOT NULL,\n  driver_id INTEGER NOT NULL,\n  price REAL NOT NULL,\n  notes TEXT,\n  status TEXT CHECK(status IN ('Pending','Accepted','Rejected')) NOT NULL DEFAULT 'Pending',\n  created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,\n  FOREIGN KEY(shipment_id) REFERENCES shipments(id) ON DELETE CASCADE,\n  FOREIGN KEY(driver_id) REFERENCES users(id) ON DELETE CASCADE\n);\n\nCREATE TABLE IF NOT EXISTS bookings (\n  id INTEGER PRIMARY KEY AUTOINCREMENT,\n  shipment_id INTEGER NOT NULL,\n  driver_id INTEGER NOT NULL,\n  agreed_price REAL NOT NULL,\n  status TEXT NOT NULL,\n  created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,\n  FOREIGN KEY(shipment_id) REFERENCES shipments(id) ON DELETE CASCADE,\n  FOREIGN KEY(driver_id) REFERENCES users(id) ON DELETE CASCADE\n);\n\nCREATE TABLE IF NOT EXISTS messages (\n  id INTEGER PRIMARY KEY AUTOINCREMENT,\n  shipment_id INTEGER NOT NULL,\n  sender_id INTEGER NOT NULL,\n  body TEXT NOT NULL,\n  created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,\n  FOREIGN KEY(shipment_id) REFERENCES shipments(id) ON DELETE CASCADE,\n  FOREIGN KEY(sender_id) REFERENCES users(id) ON DELETE CASCADE\n);\n\nCREATE TABLE IF NOT EXISTS invoices (\n  id INTEGER PRIMARY KEY AUTOINCREMENT,\n  user_id INTEGER NOT NULL,\n  plan TEXT,\n  amount REAL NOT NULL,\n  status TEXT CHECK(status IN ('Paid','Unpaid','PastDue')) NOT NULL DEFAULT 'Unpaid',\n  due_date TEXT NOT NULL,\n  created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,\n  FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE\n);\n\nCREATE TABLE IF NOT EXISTS reports (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  reporter_id INTEGER NOT NULL,
  target_user_id INTEGER NOT NULL,
  reason TEXT NOT NULL,
  status TEXT NOT NULL DEFAULT 'Open',
  action_taken TEXT,
  created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
  FOREIGN KEY(reporter_id) REFERENCES users(id) ON DELETE CASCADE,
  FOREIGN KEY(target_user_id) REFERENCES users(id) ON DELETE CASCADE
);

CREATE TABLE IF NOT EXISTS audit_logs (\n  id INTEGER PRIMARY KEY AUTOINCREMENT,\n  actor_id INTEGER,\n  action TEXT NOT NULL,\n  target_user_id INTEGER,\n  shipment_id INTEGER,\n  invoice_id INTEGER,\n  metadata TEXT,\n  created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP\n);\n